'use strict';
let materialWeek='all',materialKind='all',materialSearch='';
function courseWeekName(week){return week<=6?FIRST_HALF_WEEKS.find(w=>w.week===week).name:SECOND_HALF_WEEKS.find(w=>w.week===week).name;}
function fileSize(bytes){return (bytes/(1024*1024)).toFixed(2)+' MB';}
function filteredMaterials(){const needle=materialSearch.trim().toLowerCase();return COURSE_MATERIALS.filter(w=>(materialWeek==='all'||w.week===Number(materialWeek))&&(!needle||('week '+w.week+' '+courseWeekName(w.week)).toLowerCase().includes(needle)));}
function renderMaterials(){const weeks=filteredMaterials();document.getElementById('materials-count').textContent=weeks.length+' weeks · '+weeks.length*(materialKind==='all'?2:1)+' PDFs';document.getElementById('materials-grid').innerHTML=weeks.map(w=>`<section class="panel material-card"><span class="tag">WEEK ${w.week}</span><h2>${esc(courseWeekName(w.week))}</h2><div class="material-files">${w.files.filter(f=>materialKind==='all'||f.kind===materialKind).map(f=>`<a class="material-file" href="${f.path}" download><span><strong>${f.label}</strong><small>PDF · ${f.pages} pages · ${fileSize(f.bytes)}</small></span><span aria-hidden="true">↓</span></a>`).join('')}</div><div class="actions"><a class="secondary" href="${w.bundle}" download>Download both · ZIP ↓</a><a class="text-button" href="#banks/${w.week<=6?'weeks-1-6':'weeks-7-14'}">Related practice →</a></div></section>`).join('')||'<p class="empty">No weeks match. Try a different week or search term.</p>';}
function materialsHome(){paint(`<div class="intro"><span class="eyebrow">COURSE MATERIALS · WEEKS 1–14</span><h1>Your weekly slides and reading notes.</h1><p>Download the lecture slides and detailed reading notes shared on Moodle. All 14 weeks are available, with a PDF of each document and a ZIP containing both files for each week.</p><p class="muted">Instructor: Prof. Yanwei Wang · 28 PDFs · 14 weekly bundles</p></div><div class="program-toolbar"><label class="search"><input id="materials-search" type="search" value="${esc(materialSearch)}" placeholder="Find a week or topic…" aria-label="Search course materials"></label><label class="topic-select">Week <select id="materials-week"><option value="all">All weeks</option>${COURSE_MATERIALS.map(w=>`<option value="${w.week}" ${materialWeek===String(w.week)?'selected':''}>Week ${w.week}</option>`).join('')}</select></label><label class="topic-select">Document <select id="materials-kind">${[['all','Slides and notes'],['slides','Lecture slides'],['notes','Reading notes']].map(([v,n])=>`<option value="${v}" ${materialKind===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" id="clear-material-filters">Clear filters</button><span class="muted" id="materials-count" role="status"></span></div><div class="bank-grid materials-grid" id="materials-grid"></div><p class="code-info">PDF files are the instructor-supplied course documents. The Week 14 slide download is the comprehensive course review. Read the notes alongside the slides, then use the related practice collection.</p>`,'materials');renderMaterials();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.id==='clear-material-filters'){materialWeek=materialKind='all';materialSearch='';materialsHome();}});
document.addEventListener('input',e=>{if(e.target.id==='materials-search'){materialSearch=e.target.value;renderMaterials();}});
document.addEventListener('change',e=>{if(e.target.id==='materials-week')materialWeek=e.target.value;else if(e.target.id==='materials-kind')materialKind=e.target.value;else return;renderMaterials();});
